<?php declare(strict_types=1);
use Kulturhus\Native\Shared\Db;
use Kulturhus\Verein\{Documents,DonationCollections,DonationForms,DonationReceipts,Finance,Permissions,Registry,Settings,SettingsSchema};
use Kulturhus\Verein\Finance\Donations\Cover\{CoverDraft,CoverInput,CoverRequests,CoverSource};

/** Actual certificate producers, not inserted certificate or personal-first rows. */
function ownDonationCoverNativeContracts(PDO $db, callable $check, Closure $pdf): array
{
    $cfg=\Kulturhus\Native\TestSupport::config();
    if(($cfg['owner']??null)!=='isolated-native-ci'||($cfg['label']??null)!=='native-donation-cover-interface'||!preg_match('/\Akh_native_[a-f0-9]{24}\z/D',(string)$db->query('SELECT DATABASE()')->fetchColumn()))throw new RuntimeException('Owned native cover contracts required.');
    $club='own-cover-native';$admin='own-cover-admin';$actor='own-cover-finance';$key=static fn():string=>bin2hex(random_bytes(16));
    $db->exec("INSERT INTO clubs VALUES('own-cover-native','Own donation cover association'),('own-cover-foreign','Own foreign donation cover association');INSERT INTO actors(id,club_id,role,is_superuser)VALUES('own-cover-admin','own-cover-native','members',1),('own-cover-finance','own-cover-native','treasurer',0),('own-cover-writer','own-cover-native','treasurer',0),('own-cover-reader','own-cover-native','member',0),('own-cover-general','own-cover-native','members',0),('own-cover-foreign','own-cover-foreign','members',1)");
    $settings=new Settings($db,$admin);$roleData=['name'=>'Own cover finance only','members_access'=>'none','finance_access'=>'write','settings_access'=>false];$role=$settings->saveRole('',0,$roleData);foreach([$actor,'own-cover-writer']as$id)$settings->assignRole($id,$role,0);
    $readRole=$settings->saveRole('',0,array_replace($roleData,['name'=>'Own cover read only','finance_access'=>'read']));$settings->assignRole('own-cover-reader',$readRole,0);
    $generalRole=$settings->saveRole('',0,['name'=>'Own cover general only','members_access'=>'none','finance_access'=>'none','settings_access'=>true]);$settings->assignRole('own-cover-general',$generalRole,0);
    $settings->save('club',array_replace(SettingsSchema::defaults('club'),['name'=>'Own actual donation cover association','street'=>'Own road 1','postcode'=>'12345','city'=>'Own city']),0);
    $docs=new Documents($db,$admin);$notice=$docs->upload('own-tax-notice.pdf',$pdf('owned tax notice'),['title'=>'Own synthetic notice','kind'=>'other','scope'=>'finance','document_date'=>'2025-02-01','links'=>[]],$key());
    $tax=array_replace(SettingsSchema::defaults('tax'),['office'=>'Own synthetic tax office','number'=>'00/000/00000','purpose'=>'Förderung von Kunst und Kultur','notice_type'=>'exemption','exemption_date'=>'2025-02-01','assessment'=>'2022 bis 2024','membership_deductible'=>'no','notice_document_id'=>$notice,'receipt_signatory'=>'Own synthetic authority','receipt_authority_reviewed'=>true]);$settings->save('tax',$tax,0);
    $templates=SettingsSchema::templates('texts_donations');
    foreach(['donation','collective']as$type)$templates[$type]=['subject'=>'Own '.$type.' cover {{ZAHLBETRAG}}','intro'=>"Own complete intro 0 🙂",'message'=>"{{BRIEFANREDE}}\n{{VEREINSNAME}} thanks you for {{ZAHLBETRAG}}.",'closing'=>"Own complete closing 0"];
    $settings->save('texts_donations',$templates,0);
    $finance=new Finance($db,$admin);$account=$finance->createAccount('Own offline donation source','offline','0','2026-01-01');$registry=new Registry($db,$admin);
    $source=static function(string $type='donation',string $marker='Owned original donor')use($db,$club,$admin,$finance,$account,$registry,$docs,$key):array{
        $contact=$registry->saveContact(null,0,'person',$marker,$key().'@example.invalid',"Own original street 7\n12345 Own original city");$payments=[];$entries=[];
        foreach($type==='collective'?['25.01','40.02']:['125.50']as$i=>$amount){$entry=$finance->createEntry(['kind'=>'donation','description'=>'Own genuine cover donation '.$marker,'counterparty'=>$marker."\nOwn original street 7\n12345 Own original city",'category'=>'donations','amount'=>$amount,'document_date'=>'2026-08-01','due_date'=>'2026-08-01'],$key());$finance->assignDonationContact('entry',$entry,1,$contact);$finance->recordPayment($entry,2,$account,'2026-08-0'.($i+1));$payments[]=$finance->allocations($entry)[0]['id'];$entries[]=$entry;}
        if($type==='collective'){$service=new DonationCollections($db,$admin);$input=['contact_id'=>$contact,'from'=>'2026-01-01','to'=>'2026-08-31','payment_ids'=>$payments,'waiver_ids'=>[],'reviewed'=>'1'];$preview=$service->build($input);$document=$service->issue($input,$key(),hash('sha256',json_encode($preview,JSON_THROW_ON_ERROR)));}
        else{$input=(new DonationForms($db,$admin))->defaults('money',$entries[0])+['receipt_reviewed'=>'1'];$input['waiver']='no';$document=(new DonationReceipts($db,$admin))->issue($input,$key());}
        $file=$docs->file($document,1);$snapshot=json_decode($file['snapshot'],true,64,JSON_THROW_ON_ERROR);$receipt=$snapshot['receipt_number'];$original=CoverSource::read($db,$admin,$receipt);return ['receipt'=>$receipt,'document'=>$document,'type'=>$type,'contact'=>$contact,'entries'=>$entries,'original'=>$original,'file'=>$file,'amount_cents'=>$original['amount_cents'],'donor'=>$original['donor']];
    };
    $native=new CoverRequests($db,$actor);$single=$source();$collective=$source('collective','Own actual collective donor');$day='2026-10-22';
    $input=$native->initial($single['receipt'],$day);$input['reason']="\n0\r\nOwn native reason 🙂";
    $deny=static function(callable $fn,int $code,string $label)use($check):void{try{$fn();}catch(DomainException $failure){$check($failure->getCode()===$code,$label);return;}throw new RuntimeException('Expected own cover denial: '.$label);};
    $check(Permissions::actor($db,$actor)['members_access']==='none'&&!(new Settings($db,$actor))->canManage(),'actual cover consumer has finance writing without member or General settings management');
    $check((\Kulturhus\Verein\ManagerPageAssets::manifest()['donation-cover-native.css']['kind']??null)==='style','real manager navigation knows the donation cover stylesheet');
    $missing='Für diese ursprüngliche Bescheinigung fehlen nachweisbare Vorlagenwerte: Vorname. Ganze Brieftexte gezielt berichtigen.';$english=\Kulturhus\Native\Language\DonationCoverMessages::text($missing,\Kulturhus\Native\Language\ManagerMessages::messages('en'));$check(str_contains($english,'First name')&&str_starts_with($english,'Verified template values')&&\Kulturhus\Native\Language\DonationCoverMessages::text($missing,[])===$missing,'actual missing template value error translates finite labels and also resolves without a catalog');
    $session=[];$draft=CoverDraft::open($session,Permissions::actor($db,$actor),$input);$check(CoverDraft::get($session,Permissions::actor($db,$actor),$single['receipt'],$draft['id'])===$draft,'whole personal cover draft preserves leading LF zero CRLF and Unicode');$deny(fn()=>CoverDraft::get($session,Permissions::actor($db,'own-cover-writer'),$single['receipt'],$draft['id']),404,'another financial writer cannot inherit a private letter draft');CoverDraft::discard($session,$draft);
    $tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$before=ownOriginalDatabaseHash($db,$tables);$review=$native->prepare($input);$check($native->prepare($input)===$review&&ownOriginalDatabaseHash($db,$tables)===$before,'whole actual letter previews preserve every earlier business row');
    $deny(fn()=>$native->accept($input,$key(),$review['hash'],false),422,'missing conscious cover confirmation creates no original');
    foreach(['own-cover-reader','own-cover-general']as$id)$deny(fn()=>(new CoverRequests($db,$id))->prepare($input),403,'new cover needs current finance writing for '.$id);
    $first=$native->accept($input,$key(),$review['hash'],true);$after=ownOriginalDatabaseHash($db,$tables);$check($native->accept($input,$first['key'],$review['hash'],true)===$first&&$native->receipt($first['key'])===$first&&ownOriginalDatabaseHash($db,$tables)===$after,'known cover key returns the exact original without a second outcome');
    $check(hash('sha256',$native->pdf($first['key']))===$first['result']['sha256']&&$first['input']===$input,'private first binds the complete raw input and exact canonical stored PDF');
    foreach(['own-cover-writer'=>404,'own-cover-reader'=>404,'own-cover-general'=>403,'own-cover-foreign'=>404]as$id=>$code)$deny(fn()=>(new CoverRequests($db,$id))->receipt($first['key']),$code,'personal cover original remains private from '.$id);
    $collectiveInput=$native->initial($collective['receipt'],$day);$collectiveInput['reason']='Own real collective letter';$collectiveReview=$native->prepare($collectiveInput);$collectiveFirst=$native->accept($collectiveInput,$key(),$collectiveReview['hash'],true);
    $check($collectiveFirst['review']['source']['certificate']['template']==='collective'&&$collectiveFirst['review']['source']['certificate']['amount_cents']===6503,'actual collective producer selects its genuine two-payment amount and template');
    $check($docs->file($single['document'],1)===$single['file']&&$docs->file($collective['document'],1)===$collective['file'],'both actual statutory original PDF files and snapshots stay byte exact');
    $settings->assignRole($actor,$readRole,1);$check($native->accept($input,$first['key'],$review['hash'],true)===$first&&hash('sha256',$native->pdf($first['key']))===$first['result']['sha256'],'downgraded author retains exact own first and PDF with finance reading');$deny(fn()=>$native->prepare($input),403,'downgraded author cannot prepare a new cover');$settings->assignRole($actor,$role,2);
    $settings->assignRole('own-cover-reader',$role,1);$readRequests=new CoverRequests($db,'own-cover-reader');$readInput=$readRequests->initial($single['receipt'],$day);$readInput['reason']='Own accepted original before read-only downgrade';$readReview=$readRequests->prepare($readInput);$readFirst=$readRequests->accept($readInput,$key(),$readReview['hash'],true);$settings->assignRole('own-cover-reader',$readRole,2);
    (new DonationReceipts($db,$admin))->cancel($single['receipt'],'Own actual cancellation after both cover originals');$deny(fn()=>$native->prepare($input),409,'actual cancelled statutory source cannot produce a new cover');$check($native->receipt($first['key'])===$first&&$readRequests->receipt($readFirst['key'])===$readFirst&&hash('sha256',$readRequests->pdf($readFirst['key']))===$readFirst['result']['sha256'],'earlier exact cover originals remain readable after actual source cancellation and reader downgrade');
    $cases=[];for($i=0;$i<8;$i++)$cases[]=$source($i%2?'collective':'donation','Own browser original donor '.$i);
    $history=$source('collective','Own original history donor');$historyFirsts=[];for($i=0;$i<26;$i++){$raw=$native->initial($history['receipt'],$day);$raw['reason']='Own complete cover history 0 '.$i;$raw['text']['subject']='Own actual history letter '.$i;$prepared=$native->prepare($raw);$historyFirsts[]=$native->accept($raw,$key(),$prepared['hash'],true);}
    $page=$native->history($history['receipt'],['query'=>'Own complete cover history 0','page'=>'2']);$check($page['total']===26&&count($page['rows'])===1,'actual native cover history has a genuine second page after twenty-six canonical PDF originals');
    return compact('club','admin','actor','source','single','collective','cases','history','historyFirsts','day','native','tables','first','collectiveFirst','readFirst','finance','docs','key');
}
